actor ImageLoader {
    static let shared = ImageLoader()
    private let cache = NSCache<NSURL, UIImage>()
    private var inFlight: [URL: Task<UIImage, Error>] = [:]

    func image(for url: URL, targetSize: CGSize) async throws -> UIImage {
        if let img = cache.object(forKey: url as NSURL) { return img }
        if let task = inFlight[url] { return try await task.value }

        let task = Task<UIImage, Error> {
            let (data, _) = try await URLSession.shared.data(from: url)
            guard let img = await UIImage(data: data)?.byPreparingThumbnail(ofSize: targetSize) else {
                throw URLError(.cannotDecodeContentData)
            }
            return img
        }
        inFlight[url] = task
        defer { inFlight[url] = nil }
        let img = try await task.value
        cache.setObject(img, forKey: url as NSURL)
        return img
    }
}

final class PhotoCell: UICollectionViewCell {
    private var loadTask: Task<Void, Never>?
    let imageView = UIImageView()

    func configure(url: URL) {
        loadTask = Task { [weak self] in
            guard let self else { return }
            let img = try? await ImageLoader.shared.image(for: url, targetSize: bounds.size)
            if !Task.isCancelled { imageView.image = img }
        }
    }
    override func prepareForReuse() {
        super.prepareForReuse()
        loadTask?.cancel(); imageView.image = nil
    }
}
